package pl.takma.magazyn;
import android.app.Activity;import android.content.Intent;import android.test.InstrumentationTestCase;import android.view.View;import android.view.ViewGroup;import android.widget.Button;import android.widget.TextView;import android.view.accessibility.AccessibilityNodeInfo;import java.util.ArrayList;import java.util.List;
public class PackingUiTest extends InstrumentationTestCase {
 private Activity activity;
 private void texts(View v,List<String> out){if(v instanceof TextView)out.add(((TextView)v).getText().toString());if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)texts(g.getChildAt(i),out);}}
 private boolean has(String text){List<String> values=new ArrayList<>();getInstrumentation().runOnMainSync(()->texts(activity.getWindow().getDecorView(),values));return values.stream().anyMatch(v->v.contains(text));}
 private void expect(String text)throws Exception{for(int i=0;i<100;i++){if(has(text))return;Thread.sleep(100);}fail("Missing: "+text);}
 private Button find(View v,String text){if(v instanceof Button&&((Button)v).getText().toString().equals(text))return (Button)v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){Button b=find(g.getChildAt(i),text);if(b!=null)return b;}}return null;}
 private void click(String text)throws Exception{for(int i=0;i<100;i++){List<Boolean> found=new ArrayList<>();getInstrumentation().runOnMainSync(()->{Button b=find(activity.getWindow().getDecorView(),text);if(b!=null&&b.isEnabled()){b.performClick();found.add(true);}});if(!found.isEmpty())return;Thread.sleep(100);}fail("Button missing/disabled: "+text);}
 private void disabled(String text){getInstrumentation().runOnMainSync(()->{Button b=find(activity.getWindow().getDecorView(),text);assertNotNull(b);assertFalse(b.isEnabled());});}
 private void dialog(String text)throws Exception{for(int i=0;i<50;i++){AccessibilityNodeInfo root=getInstrumentation().getUiAutomation().getRootInActiveWindow();if(root!=null)for(AccessibilityNodeInfo n:root.findAccessibilityNodeInfosByText(text)){if(n.getText()!=null&&n.getText().toString().equalsIgnoreCase(text)&&n.isClickable()){n.performAction(AccessibilityNodeInfo.ACTION_CLICK);return;}}Thread.sleep(100);}fail("Dialog missing: "+text);}
 private void scan(String code){getInstrumentation().getContext().sendBroadcast(new Intent(BuildConfig.APPLICATION_ID+".BARCODE").setPackage(BuildConfig.APPLICATION_ID).putExtra("data",code));}
 public void testPrepareDemoContainerForPhysicalScan()throws Exception{activity=getInstrumentation().startActivitySync(new Intent(getInstrumentation().getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));expect("2 zamówienia do kompletacji");click("Rozpocznij kompletację");expect("Kompletacja #1002");scan("TAK-DEMO-01");expect("1 / 1 szt.");click("Zeskanuj pojemnik");expect("Kod pojemnika");scan("BOX-01");expect("Pojemnik: BOX-01");click("Zakończ kompletację");dialog("Zakończ");expect("Kompletacja zakończona");click("Przejdź do pakowania");expect("Do pakowania: 1");}
 public void testResetCompletedDemoTerminal()throws Exception{activity=getInstrumentation().startActivitySync(new Intent(getInstrumentation().getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));expect("Zamówienia");click("Ustawienia terminala");click("Aktywuj ponownie przez QR");dialog("Przygotuj terminal");expect("Zeskanuj kod QR");}
 public void testPickingContainerPackingRestartAndPackedStatus()throws Exception{
  String qr=((android.test.InstrumentationTestRunner)getInstrumentation()).getArguments().getString("activationQr");assertNotNull("Pass demo QR",qr);
  activity=getInstrumentation().startActivitySync(new Intent(getInstrumentation().getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));getInstrumentation().waitForIdleSync();if(!((android.test.InstrumentationTestRunner)getInstrumentation()).getArguments().getString("resume", "false").equals("true")){scan(qr);expect("3 zamówienia do kompletacji");
  click("Rozpocznij kompletację");expect("Kompletacja #1001");scan("TAK-100150");expect("1 / 3 szt.");scan("TAK-100150");expect("2 / 3 szt.");scan("TAK-W110");expect("3 / 3 szt.");disabled("Zakończ kompletację");
  click("Zeskanuj pojemnik");expect("Kod pojemnika");scan("BOX-01");expect("Pojemnik: BOX-01");click("Zakończ kompletację");dialog("Zakończ");expect("Kompletacja zakończona");click("Przejdź do pakowania");expect("Do pakowania: 1");scan("BOX-01");expect("Sprawdzono 0 / 3 szt.");disabled("Zakończ pakowanie");
  scan("WRONG");expect("Ten produkt nie należy");scan("TAK-100150");expect("Sprawdzono 1 / 3 szt.");scan("TAK-100150");expect("Sprawdzono 2 / 3 szt.");
  }
  android.app.Instrumentation.ActivityMonitor monitor=getInstrumentation().addMonitor(MainActivity.class.getName(),null,false);getInstrumentation().runOnMainSync(()->activity.recreate());activity=getInstrumentation().waitForMonitorWithTimeout(monitor,10000);getInstrumentation().removeMonitor(monitor);assertNotNull("Recreated activity",activity);expect("Sprawdzono 2 / 3 szt.");
  scan("TAK-W110");expect("Sprawdzono 3 / 3 szt.");scan("TAK-W110");expect("Sprawdzono już wymaganą ilość");click("Cofnij ostatnią sztukę");expect("Sprawdzono 2 / 3 szt.");disabled("Zakończ pakowanie");scan("TAK-W110");expect("Sprawdzono 3 / 3 szt.");click("Zakończ pakowanie");dialog("Spakowane");expect("Spakowane");click("Wróć do pakowania");expect("Do pakowania: 0");
 }
}
